// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// GetHealth Liveness and readiness
	// (GET /healthz)
	GetHealth(ctx context.Context, request GetHealthRequestObject) (GetHealthResponseObject, error)
	// Login Log in with email and password (starts a new token family)
	// (POST /v1/auth/login)
	Login(ctx context.Context, request LoginRequestObject) (LoginResponseObject, error)
	// Logout Revoke the refresh token family
	// (POST /v1/auth/logout)
	Logout(ctx context.Context, request LogoutRequestObject) (LogoutResponseObject, error)
	// RefreshSession Rotate the refresh token
	// (POST /v1/auth/refresh)
	RefreshSession(ctx context.Context, request RefreshSessionRequestObject) (RefreshSessionResponseObject, error)
	// Register Start registration (emails a 6-digit verification code)
	// (POST /v1/auth/register)
	Register(ctx context.Context, request RegisterRequestObject) (RegisterResponseObject, error)
	// VerifyEmail Confirm the emailed code and set the password; creates the account, starts the trial, issues tokens
	// (POST /v1/auth/verify-email)
	VerifyEmail(ctx context.Context, request VerifyEmailRequestObject) (VerifyEmailResponseObject, error)
	// ResendVerification Email a new verification code for a pending sign-up
	// (POST /v1/auth/verify-email/resend)
	ResendVerification(ctx context.Context, request ResendVerificationRequestObject) (ResendVerificationResponseObject, error)
	// RegisterDevice Register or refresh a push token
	// (POST /v1/devices)
	RegisterDevice(ctx context.Context, request RegisterDeviceRequestObject) (RegisterDeviceResponseObject, error)
	// UnregisterDevice Remove a push token (logout / opt-out)
	// (DELETE /v1/devices/{deviceId})
	UnregisterDevice(ctx context.Context, request UnregisterDeviceRequestObject) (UnregisterDeviceResponseObject, error)
	// ListExpenseCategories Expense categories with deductibility hints per regime
	// (GET /v1/expense-categories)
	ListExpenseCategories(ctx context.Context, request ListExpenseCategoriesRequestObject) (ListExpenseCategoriesResponseObject, error)
	// ListEnabledFlags Modules enabled for the client (UX only; server enforces)
	// (GET /v1/flags)
	ListEnabledFlags(ctx context.Context, request ListEnabledFlagsRequestObject) (ListEnabledFlagsResponseObject, error)
	// ListLegalDocuments Current privacy notices and terms
	// (GET /v1/legal/documents)
	ListLegalDocuments(ctx context.Context, request ListLegalDocumentsRequestObject) (ListLegalDocumentsResponseObject, error)
	// DeleteMe Delete the account and all its data (irreversible; requires the current password)
	// (DELETE /v1/me)
	DeleteMe(ctx context.Context, request DeleteMeRequestObject) (DeleteMeResponseObject, error)
	// GetMe Current user profile
	// (GET /v1/me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)
	// UpdateMe Update profile (name only; email change is out of scope)
	// (PATCH /v1/me)
	UpdateMe(ctx context.Context, request UpdateMeRequestObject) (UpdateMeResponseObject, error)
	// ListRegimes Regime catalog filtered by person type
	// (GET /v1/regimes)
	ListRegimes(ctx context.Context, request ListRegimesRequestObject) (ListRegimesResponseObject, error)
	// GetReminderSettings Reminder preferences (defaults if never set)
	// (GET /v1/reminder-settings)
	GetReminderSettings(ctx context.Context, request GetReminderSettingsRequestObject) (GetReminderSettingsResponseObject, error)
	// PutReminderSettings Replace reminder preferences
	// (PUT /v1/reminder-settings)
	PutReminderSettings(ctx context.Context, request PutReminderSettingsRequestObject) (PutReminderSettingsResponseObject, error)
	// GetSubscription Access status (trial, pro, comp, read-only) and plan
	// (GET /v1/subscription)
	GetSubscription(ctx context.Context, request GetSubscriptionRequestObject) (GetSubscriptionResponseObject, error)
	// SyncSubscription Pull current state from RevenueCat (post-purchase / restore)
	// (POST /v1/subscription/sync)
	SyncSubscription(ctx context.Context, request SyncSubscriptionRequestObject) (SyncSubscriptionResponseObject, error)
	// GetTaxCalendar Monthly due dates for a year (day 17 moved past weekends/holidays)
	// (GET /v1/tax-calendar)
	GetTaxCalendar(ctx context.Context, request GetTaxCalendarRequestObject) (GetTaxCalendarResponseObject, error)
	// ListTaxpayers Taxpayers managed by the user
	// (GET /v1/taxpayers)
	ListTaxpayers(ctx context.Context, request ListTaxpayersRequestObject) (ListTaxpayersResponseObject, error)
	// CreateTaxpayer Create a taxpayer (onboarding order - person type, RFC, regimes, options)
	// (POST /v1/taxpayers)
	CreateTaxpayer(ctx context.Context, request CreateTaxpayerRequestObject) (CreateTaxpayerResponseObject, error)
	// DeleteTaxpayer Permanently delete a taxpayer and its records (irreversible)
	// (DELETE /v1/taxpayers/{taxpayerId})
	DeleteTaxpayer(ctx context.Context, request DeleteTaxpayerRequestObject) (DeleteTaxpayerResponseObject, error)
	// GetTaxpayer Get a taxpayer
	// (GET /v1/taxpayers/{taxpayerId})
	GetTaxpayer(ctx context.Context, request GetTaxpayerRequestObject) (GetTaxpayerResponseObject, error)
	// UpdateTaxpayer Rename a taxpayer (person type and RFC are immutable)
	// (PATCH /v1/taxpayers/{taxpayerId})
	UpdateTaxpayer(ctx context.Context, request UpdateTaxpayerRequestObject) (UpdateTaxpayerResponseObject, error)
	// ArchiveTaxpayer Archive (hide) a taxpayer, keeping its data
	// (POST /v1/taxpayers/{taxpayerId}/archive)
	ArchiveTaxpayer(ctx context.Context, request ArchiveTaxpayerRequestObject) (ArchiveTaxpayerResponseObject, error)
	// GetDashboard Home for the active taxpayer
	// (GET /v1/taxpayers/{taxpayerId}/dashboard)
	GetDashboard(ctx context.Context, request GetDashboardRequestObject) (GetDashboardResponseObject, error)
	// GetTaxpayerEstimate Monthly IVA + provisional ISR estimate, per regime and total
	// (GET /v1/taxpayers/{taxpayerId}/estimates)
	GetTaxpayerEstimate(ctx context.Context, request GetTaxpayerEstimateRequestObject) (GetTaxpayerEstimateResponseObject, error)
	// GetEstimateBreakdown Step-by-step breakdown with legal basis for one regime
	// (GET /v1/taxpayers/{taxpayerId}/estimates/{period}/breakdown)
	GetEstimateBreakdown(ctx context.Context, request GetEstimateBreakdownRequestObject) (GetEstimateBreakdownResponseObject, error)
	// ListExpenses List a month's expenses (keyset pagination) with period totals
	// (GET /v1/taxpayers/{taxpayerId}/expenses)
	ListExpenses(ctx context.Context, request ListExpensesRequestObject) (ListExpensesResponseObject, error)
	// CreateExpense Record an expense (trial cap enforced)
	// (POST /v1/taxpayers/{taxpayerId}/expenses)
	CreateExpense(ctx context.Context, request CreateExpenseRequestObject) (CreateExpenseResponseObject, error)
	// DeleteExpense Soft-delete an expense (undo via restore)
	// (DELETE /v1/taxpayers/{taxpayerId}/expenses/{expenseId})
	DeleteExpense(ctx context.Context, request DeleteExpenseRequestObject) (DeleteExpenseResponseObject, error)
	// GetExpense Get an expense
	// (GET /v1/taxpayers/{taxpayerId}/expenses/{expenseId})
	GetExpense(ctx context.Context, request GetExpenseRequestObject) (GetExpenseResponseObject, error)
	// UpdateExpense Edit an expense
	// (PATCH /v1/taxpayers/{taxpayerId}/expenses/{expenseId})
	UpdateExpense(ctx context.Context, request UpdateExpenseRequestObject) (UpdateExpenseResponseObject, error)
	// RestoreExpense Undo a delete
	// (POST /v1/taxpayers/{taxpayerId}/expenses/{expenseId}/restore)
	RestoreExpense(ctx context.Context, request RestoreExpenseRequestObject) (RestoreExpenseResponseObject, error)
	// GetHistory Monthly summaries for a fiscal year
	// (GET /v1/taxpayers/{taxpayerId}/history)
	GetHistory(ctx context.Context, request GetHistoryRequestObject) (GetHistoryResponseObject, error)
	// MarkHistoryViewed Mark a month as viewed (stores the current records fingerprint)
	// (POST /v1/taxpayers/{taxpayerId}/history/{period}/viewed)
	MarkHistoryViewed(ctx context.Context, request MarkHistoryViewedRequestObject) (MarkHistoryViewedResponseObject, error)
	// ListIncomes List a month's incomes (keyset pagination) with period totals
	// (GET /v1/taxpayers/{taxpayerId}/incomes)
	ListIncomes(ctx context.Context, request ListIncomesRequestObject) (ListIncomesResponseObject, error)
	// CreateIncome Record an income (trial cap enforced)
	// (POST /v1/taxpayers/{taxpayerId}/incomes)
	CreateIncome(ctx context.Context, request CreateIncomeRequestObject) (CreateIncomeResponseObject, error)
	// DeleteIncome Soft-delete an income (undo via restore)
	// (DELETE /v1/taxpayers/{taxpayerId}/incomes/{incomeId})
	DeleteIncome(ctx context.Context, request DeleteIncomeRequestObject) (DeleteIncomeResponseObject, error)
	// GetIncome Get an income
	// (GET /v1/taxpayers/{taxpayerId}/incomes/{incomeId})
	GetIncome(ctx context.Context, request GetIncomeRequestObject) (GetIncomeResponseObject, error)
	// UpdateIncome Edit an income (402 when access is read-only)
	// (PATCH /v1/taxpayers/{taxpayerId}/incomes/{incomeId})
	UpdateIncome(ctx context.Context, request UpdateIncomeRequestObject) (UpdateIncomeResponseObject, error)
	// RestoreIncome Undo a delete
	// (POST /v1/taxpayers/{taxpayerId}/incomes/{incomeId}/restore)
	RestoreIncome(ctx context.Context, request RestoreIncomeRequestObject) (RestoreIncomeResponseObject, error)
	// AddTaxpayerRegime Add a regime to a taxpayer
	// (POST /v1/taxpayers/{taxpayerId}/regimes)
	AddTaxpayerRegime(ctx context.Context, request AddTaxpayerRegimeRequestObject) (AddTaxpayerRegimeResponseObject, error)
	// ArchiveTaxpayerRegime Archive a regime with an end period (records are kept)
	// (DELETE /v1/taxpayers/{taxpayerId}/regimes/{regimeCode})
	ArchiveTaxpayerRegime(ctx context.Context, request ArchiveTaxpayerRegimeRequestObject) (ArchiveTaxpayerRegimeResponseObject, error)
	// UpdateTaxpayerRegime Update regime options
	// (PATCH /v1/taxpayers/{taxpayerId}/regimes/{regimeCode})
	UpdateTaxpayerRegime(ctx context.Context, request UpdateTaxpayerRegimeRequestObject) (UpdateTaxpayerRegimeResponseObject, error)
	// GetTaxInputs Tax inputs (YTD, coeficiente, losses, prior payments) with which keys are required
	// (GET /v1/taxpayers/{taxpayerId}/regimes/{regimeCode}/tax-inputs)
	GetTaxInputs(ctx context.Context, request GetTaxInputsRequestObject) (GetTaxInputsResponseObject, error)
	// PutTaxInputs Replace tax inputs for the fiscal year
	// (PUT /v1/taxpayers/{taxpayerId}/regimes/{regimeCode}/tax-inputs)
	PutTaxInputs(ctx context.Context, request PutTaxInputsRequestObject) (PutTaxInputsResponseObject, error)
	// ReceiveRevenueCatWebhook RevenueCat webhook receiver (idempotent by event id)
	// (POST /v1/webhooks/revenuecat)
	ReceiveRevenueCatWebhook(ctx context.Context, request ReceiveRevenueCatWebhookRequestObject) (ReceiveRevenueCatWebhookResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

// GetHealth operation middleware
func (sh *strictHandler) GetHealth(w http.ResponseWriter, r *http.Request) {
	var request GetHealthRequestObject

	handler := func(ctx context.Context, w http.ResponseWriter, r *http.Request, request interface{}) (interface{}, error) {
		return sh.ssi.GetHealth(ctx, request.(GetHealthRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "GetHealth")
	}

	response, err := handler(r.Context(), w, r, request)

	if err != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, err)
	} else if validResponse, ok := response.(GetHealthResponseObject); ok {
		if err := validResponse.VisitGetHealthResponse(w); err != nil {
			sh.options.ResponseErrorHandlerFunc(w, r, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, fmt.Errorf("unexpected response type: %T", response))
	}
}

